/* 基础字体设置 */
.konata-thinking-wrapper {
    display: block;
    margin: 12px 0;
    font-family: system-ui, -apple-system, sans-serif;
    -webkit-tap-highlight-color: transparent;
}

/* 主容器：毛玻璃效果 */
.konata-thinking-details {
    background: rgba(15, 23, 42, 0.6);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 12px;
    overflow: hidden;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

/* 展开状态：加深背景，高亮边框 */
.konata-thinking-details[open] {
    background: rgba(2, 6, 23, 0.85);
    border-color: rgba(139, 92, 246, 0.5);
    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3);
}

/* 标题栏 */
.konata-thinking-summary {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    cursor: pointer;
    user-select: none;
    color: #cbd5e1;
    font-size: 14px;
    font-weight: 600;
}

/* 隐藏默认三角 */
.konata-thinking-summary::-webkit-details-marker {
    display: none;
}

/* 标题内容区 */
.konata-title-content {
    display: flex;
    align-items: center;
    gap: 8px;
}

/* 图标旋转 */
.konata-icon {
    display: inline-block;
    transition: transform 0.3s ease;
}
.konata-thinking-details[open] .konata-icon {
    transform: rotate(90deg);
    color: #a78bfa;
}

/* 展开箭头 */
.konata-arrow {
    width: 20px;
    height: 20px;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.7;
    transition: transform 0.3s ease;
}
.konata-arrow::after {
    content: '';
    width: 6px;
    height: 6px;
    border-right: 2px solid currentColor;
    border-bottom: 2px solid currentColor;
    transform: rotate(45deg) translate(-1px, -1px);
}
.konata-thinking-details[open] .konata-arrow {
    transform: rotate(180deg);
    opacity: 1;
    color: #a78bfa;
}

/* 内容区域：保留滚动条与正确换行 */
.konata-thinking-content {
    padding: 12px 16px 16px;
    color: #cbd5e1;
    font-size: 13.5px;
    line-height: 1.6;
    border-top: 1px solid rgba(255, 255, 255, 0.05);
    max-height: 350px;
    overflow-y: auto;
    overflow-x: hidden;
    -webkit-overflow-scrolling: touch;
    animation: konataFadeIn 0.3s ease;
    white-space: pre-wrap;       /* 核心修复：保留空格和换行符 */
    overflow-wrap: break-word;   /* 核心修复：防止长单词溢出 */
    word-break: break-word;      /* 兼容性增强 */
}

@keyframes konataFadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

/* 滚动条样式 */
.konata-thinking-content::-webkit-scrollbar {
    width: 4px;
}
.konata-thinking-content::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 4px;
}

/* Markdown 元素样式 */
.konata-thinking-content p { margin: 8px 0; }
.konata-thinking-content code {
    background: rgba(0, 0, 0, 0.3);
    color: #e879f9;
    padding: 2px 5px;
    border-radius: 4px;
    font-family: monospace;
    font-size: 0.9em;
}
.konata-thinking-content pre {
    background: rgba(0, 0, 0, 0.4);
    padding: 10px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.1);
    overflow-x: auto;
    white-space: pre; /* 代码块内部保持原有格式 */
}




